import Foundation

extension FichasProntas {
    /// Prontuário médico – Ortopedia de Alagoa Grande (Prefeitura), igual ao modelo em Word: nome, endereço e
    /// CNS do cadastro e 19 linhas de texto livre ({{ATENDIMENTO}}, {{ATENDIMENTO_LINHA_2}}…). O rodapé
    /// mantém a data automática do Word, o endereço e a assinatura.
    static let arquivoAlagoaGrande = "ficha-alagoa-grande-v2.docx"
    static let nomeAlagoaGrande = "Prontuário médico – Alagoa Grande"
    static let idAlagoaGrande = UUID(uuidString: "8B2E4F60-1C3D-4A5B-9E7F-2D4C6A8B0E1F")!

    static var alagoaGrande: Data? { Data(base64Encoded: alagoaGrandeBase64) }

    private static let alagoaGrandeBase64 = ""
}
